PRAGMA foreign_keys = ON;

/*
Now, when running Q2:
   SELECT CDSCode FROM FRPM WHERE ("ENROLLMENT (K-12)" + "ENROLLMENT (AGES 5-17)") > 500
it returns both 'orphan' (300+250=550) and 'valid' (400+200=600).

But Q1:
   SELECT T2.CDSCode FROM SCHOOLS AS T1
   INNER JOIN FRPM AS T2 ON T1.CDSCode = T2.CDSCode
   WHERE T2."ENROLLMENT (K-12)" + T2."ENROLLMENT (AGES 5-17)" > 500
will only return 'valid' since there is no matching SCHOOLS row for 'orphan'.
*/

