counterexample:
-- No counterexample exists under the given schema and constraints, because for all valid test data the two queries produce the same result.

-- For example, the following INSERT statements show a plausible dataset (note that the percentages computed by Q1 and Q2 will be equal):

INSERT INTO PUBLISHER (ID, PUBLISHER_NAME) VALUES (1, 'Marvel Comics');
INSERT INTO PUBLISHER (ID, PUBLISHER_NAME) VALUES (2, 'DC Comics');

INSERT INTO SUPERHERO (ID, GENDER_ID, EYE_COLOUR_ID, HAIR_COLOUR_ID, SKIN_COLOUR_ID, RACE_ID, PUBLISHER_ID, ALIGNMENT_ID) 
VALUES (1, 1, 1, 1, 1, 1, 1, 1);
INSERT INTO SUPERHERO (ID, GENDER_ID, EYE_COLOUR_ID, HAIR_COLOUR_ID, SKIN_COLOUR_ID, RACE_ID, PUBLISHER_ID, ALIGNMENT_ID) 
VALUES (2, 1, 1, 1, 1, 1, 1, 1);

INSERT INTO SUPERPOWER (ID, POWER_NAME) VALUES (1, 'Super Strength');
INSERT INTO SUPERPOWER (ID, POWER_NAME) VALUES (2, 'Invisibility');

-- Associate superhero 1 with two power rows (one 'Super Strength' and one not) and superhero 2 with one 'Super Strength' row
INSERT INTO HERO_POWER (HERO_ID, POWER_ID) VALUES (1, 1);
INSERT INTO HERO_POWER (HERO_ID, POWER_ID) VALUES (1, 2);
INSERT INTO HERO_POWER (HERO_ID, POWER_ID) VALUES (2, 1);

-- When running Q1 and Q2 on this data both will join to yield 3 rows overall:
-- For superhero 1: one row with 'Super Strength' and one with 'Invisibility'; for superhero 2: one row with 'Super Strength'.
-- Thus the numerator in each query is 2 (the two 'Super Strength' rows) and the denominator is 3, yielding 66.67% in both cases.

-- Because all duplicate effects are identical in both queries, no counterexample (i.e. test data yielding a different result between Q1 and Q2) can be generated without violating the schema constraints.

