INSERT INTO EVENT (event_id) VALUES ('event1');
INSERT INTO BUDGET (budget_id, link_to_event) VALUES ('budget1', 'event1');

-- Insert expense rows for the member; both queries will aggregate these rows identically
INSERT INTO EXPENSE (expense_id, cost, link_to_member, link_to_budget) VALUES ('exp1', 10.0, 'rec4BLdZHS2Blfp4v', 'budget1');
INSERT INTO EXPENSE (expense_id, cost, link_to_member, link_to_budget) VALUES ('exp2', 20.0, 'rec4BLdZHS2Blfp4v', 'budget1');

-- Running both Q1 and Q2 on the data above produces:
--   first_name: Alice
--   last_name: Smith
--   SUM(cost): 30.0

-- Therefore, under the given schema no counterexample exists where the two queries yield different results.

